package finance.data.serializer;

import finance.insurance.*;
import net.minecraft.nbt.*;
import java.util.UUID;

public final class InsuranceDataSerializer {
 private InsuranceDataSerializer(){}
 public static void save(CompoundTag root){CompoundTag state=new CompoundTag();InsurancePool pool=InsuranceManager.pool();state.putBoolean("Initialized",pool.initialized());state.putBoolean("Paused",pool.newBusinessPaused());state.putLong("Capital",pool.initialCapital());state.putLong("Premiums",pool.premiumsReceived());state.putLong("ClaimsPaid",pool.claimsPaid());state.putLong("Costs",pool.operatingCosts());state.putLong("LastDay",pool.lastProcessedDay());ListTag policies=new ListTag();for(InsurancePolicy p:InsuranceManager.policies().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",p.id());t.putString("Product",p.product().name());t.putUUID("Holder",p.holderId());if(p.companyId()!=null)t.putUUID("Company",p.companyId());t.putUUID("Object",p.insuredObjectId());t.putUUID("Beneficiary",p.beneficiaryId());t.putLong("Effective",p.effectiveDay());t.putLong("Expiry",p.expiryDay());t.putString("Status",p.status().name());t.putLong("Coverage",p.coverageLimit());t.putLong("Deductible",p.deductible());t.putInt("Ratio",p.payoutRatioBps());t.putLong("Remaining",p.remainingLimit());t.putLong("Premium",p.premium());t.putUUID("PremiumTx",p.premiumTransactionId());t.putInt("Risk",p.riskFactorBps());t.putInt("Version",p.version());t.putLong("Updated",p.lastUpdatedDay());policies.add(t);}state.put("Policies",policies);ListTag claims=new ListTag();for(InsuranceClaim c:InsuranceManager.claims().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",c.id());t.putUUID("Policy",c.policyId());t.putUUID("Event",c.eventId());t.putUUID("Applicant",c.applicantId());t.putLong("Reported",c.reportedAmount());t.putLong("Loss",c.verifiedLoss());t.putLong("Approved",c.approvedAmount());t.putLong("Created",c.createdDay());t.putLong("Reviewed",c.reviewedDay());t.putLong("ApprovedDay",c.approvedDay());t.putString("Status",c.status().name());t.putString("Reason",c.reason());t.putString("Evidence",c.evidence());t.putLong("Paid",c.paidAmount());t.putLong("PaymentDay",c.lastPaymentDay());if(c.paymentTransactionId()!=null)t.putUUID("PaymentTx",c.paymentTransactionId());claims.add(t);}state.put("Claims",claims);ListTag events=new ListTag();for(InsuredLossEvent e:InsuranceManager.events().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",e.id());t.putString("Type",e.type().name());t.putUUID("Company",e.companyId());t.putUUID("Object",e.objectId());t.putLong("Day",e.occurredDay());t.putLong("End",e.endDay());t.putLong("Seed",e.seed());t.putInt("Intensity",e.intensityBps());t.putString("Commodity",e.commodityId());t.putLong("Before",e.quantityBefore());t.putLong("Lost",e.quantityLost());t.putLong("Price",e.unitPrice());t.putLong("Loss",e.verifiedLoss());t.putLong("Offset",e.offsetCompensation());t.putString("Evidence",e.evidence());t.putBoolean("Processed",e.processed());events.add(t);}state.put("Events",events);ListTag keys=new ListTag();for(String k:InsuranceManager.keys()){CompoundTag t=new CompoundTag();t.putString("Key",k);keys.add(t);}state.put("Keys",keys);root.put("Insurance",state);}
 public static void load(CompoundTag root){InsuranceManager.clearDirect();if(!root.contains("Insurance",Tag.TAG_COMPOUND))return;CompoundTag s=root.getCompound("Insurance");InsuranceManager.pool().restore(s.getBoolean("Initialized"),s.getBoolean("Paused"),Math.max(0,s.getLong("Capital")),Math.max(0,s.getLong("Premiums")),Math.max(0,s.getLong("ClaimsPaid")),Math.max(0,s.getLong("Costs")),s.getLong("LastDay"));for(Tag raw:s.getList("Policies",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;UUID id=NbtDataSupport.readUuidOrNull(t,"Id"),holder=NbtDataSupport.readUuidOrNull(t,"Holder"),company=NbtDataSupport.readUuidOrNull(t,"Company"),object=NbtDataSupport.readUuidOrNull(t,"Object"),beneficiary=NbtDataSupport.readUuidOrNull(t,"Beneficiary"),tx=NbtDataSupport.readUuidOrNull(t,"PremiumTx");InsuranceManager.putPolicyDirect(new InsurancePolicy(id,InsuranceProduct.valueOf(t.getString("Product")),holder,company,object,beneficiary,t.getLong("Effective"),t.getLong("Expiry"),PolicyStatus.valueOf(t.getString("Status")),t.getLong("Coverage"),t.getLong("Deductible"),t.getInt("Ratio"),t.getLong("Remaining"),t.getLong("Premium"),tx,t.getInt("Risk"),t.getInt("Version"),t.getLong("Updated")));}catch(Exception ignored){}}for(Tag raw:s.getList("Events",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;InsuranceManager.putEventDirect(new InsuredLossEvent(t.getUUID("Id"),RiskEventType.valueOf(t.getString("Type")),t.getUUID("Company"),t.getUUID("Object"),t.getLong("Day"),t.getLong("End"),t.getLong("Seed"),t.getInt("Intensity"),t.getString("Commodity"),t.getLong("Before"),t.getLong("Lost"),t.getLong("Price"),t.getLong("Loss"),t.getLong("Offset"),t.getString("Evidence"),t.getBoolean("Processed")));}catch(Exception ignored){}}for(Tag raw:s.getList("Claims",Tag.TAG_COMPOUND)){try{CompoundTag t=(CompoundTag)raw;UUID payment=NbtDataSupport.readUuidOrNull(t,"PaymentTx");InsuranceManager.putClaimDirect(new InsuranceClaim(t.getUUID("Id"),t.getUUID("Policy"),t.getUUID("Event"),t.getUUID("Applicant"),t.getLong("Reported"),t.getLong("Loss"),t.getLong("Approved"),t.getLong("Created"),t.getLong("Reviewed"),t.getLong("ApprovedDay"),ClaimStatus.valueOf(t.getString("Status")),t.getString("Reason"),t.getString("Evidence"),t.getLong("Paid"),t.getLong("PaymentDay"),payment));}catch(Exception ignored){}}for(Tag raw:s.getList("Keys",Tag.TAG_COMPOUND))InsuranceManager.putKeyDirect(((CompoundTag)raw).getString("Key"));}
}
